import csv, json, datetime as dt
rows=list(csv.DictReader(open("data.csv")))
data={}  # band -> list of (date, value)
for r in rows:
    d=dt.date.fromisoformat(r["date"])
    data.setdefault(r["band"],[]).append((d,float(r["y"])))
for b in data: data[b].sort()
targets=[(r["period_id"],dt.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]
pred={}
for pid,d in targets:
    pred[pid]={}
    for b,series in data.items():
        # seasonal analogs: same day-of-year window +-16 days, any year
        cands=[]
        for hd,v in series:
            if abs((hd.replace(year=2001)-d.replace(year=2001)).days)<=16:
                cands.append((hd,v))
        # weight by recency and closeness
        num=den=0.0
        for hd,v in cands:
            w=0.5**( (d-hd).days/365.0 ) * (1.0 - abs((hd.replace(year=2001)-d.replace(year=2001)).days)/20.0)
            num+=w*v; den+=w
        seas=num/den
        # level adjustment: recent mean minus seasonal mean at recent times
        rec=series[-6:]
        rnum=rden=0.0
        for hd,v in rec:
            # seasonal value at hd
            n2=d2=0.0
            for h2,v2 in series:
                if abs((h2.replace(year=2001)-hd.replace(year=2001)).days)<=16:
                    w2=0.5**((hd-h2).days/365.0)
                    n2+=w2*v2; d2+=w2
            if d2>0:
                rnum+=v-n2/d2; rden+=1
        adj=rnum/rden if rden else 0
        pred[pid][b]=round(seas+0.5*adj,4)
json.dump({"prediction":pred,"rationale":"Seasonal-analog forecast: for each target visit, each band's value is a recency- and phase-weighted average of the parcel's own historical observations at the same time of year (±16-day window), plus a damped (0.5) level offset from the parcel's recent 6 visits versus their seasonal analogs. This is a Synthetic Historical Control style transfer of the parcel's own recurrent seasonal pattern."},open("answer.json","w"),indent=1)
print(json.dumps(pred["P118"]), json.dumps(pred["P144"]))
