import csv, datetime as dt, json, statistics
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
times=sorted({(r["period_id"],r["date"]) for r in rows}, key=lambda x:x[1])
vals=defaultdict(dict)
for r in rows: vals[r["band"]][r["period_id"]]=float(r["y"])
hist=[(p,dt.date.fromisoformat(d)) for p,d in times]
bands=sorted(vals)

def donor_avg(b, td, exclude=None):
    cands=[]
    for hp,h in hist:
        if hp==exclude: continue
        if h.year<td.year and abs((h-td.replace(year=h.year)).days)<=7:
            cands.append(vals[b][hp])
    return sum(cands)/len(cands) if cands else None

# leave-one-year-out backtest to estimate bias
errs=defaultdict(list)
for p,d in times:
    td=dt.date.fromisoformat(d)
    for b in bands:
        cands=[]
        for hp,h in hist:
            if hp==p or h.year==td.year: continue
            if abs((h-td.replace(year=h.year)).days)<=7:
                cands.append(vals[b][hp])
        if cands:
            errs[b].append(vals[b][p]-sum(cands)/len(cands))
bias={b:statistics.mean(errs[b]) for b in bands}
mae={b:statistics.mean(abs(e) for e in errs[b]) for b in bands}
print("bias",bias); print("mae",mae)

targets=[(r["period_id"],dt.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]
pred={}
for p,td in targets:
    pred[p]={b: round(donor_avg(b,td)+bias[b],4) for b in bands}
json.dump({"prediction":pred}, open("pred_tmp.json","w"), indent=1)
print(pred["P221"]); print(pred["P240"]); print(pred["P271"])
