import csv, datetime, statistics
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
d=defaultdict(dict); dates={}
for r in rows:
    d[r["period_id"]][r["band"]]=float(r["y"])
    dates[r["period_id"]]=datetime.date.fromisoformat(r["date"])
times=sorted(d,key=lambda p:int(p[1:]))
bands=["VH","VV","VV-VH"]
def doy(date): return date.timetuple().tm_yday
def angdist(a,b):
    diff=abs(a-b)%365
    return min(diff,365-diff)
def predict(date, window=20, halflife_days=365*1.5, train=None):
    preds={}
    tr = train if train is not None else times
    for b in bands:
        num=den=0.0
        for t in tr:
            dd=angdist(doy(date),doy(dates[t]))
            if dd<=window:
                w=0.5**(dd/(window/2)) * 0.5**(((date-dates[t]).days)/halflife_days)
                num+=w*d[t][b]; den+=w
        preds[b]=num/den
    return preds
errs=defaultdict(list)
for t in times:
    dt=dates[t]
    if dt.month in (9,10,11,12) and dt.year>=2021:
        train=[x for x in times if (dt-dates[x]).days>30]
        p=predict(dt, train=train)
        for b in bands: errs[b].append(p[b]-d[t][b])
for b in bands:
    e=errs[b]
    print(b,"rmse",round(statistics.mean(x*x for x in e)**.5,3),"bias",round(statistics.mean(e),3))
for b in bands:
    e=[d[times[i-1]][b]-d[t][b] for i,t in enumerate(times) if i>0]
    print(b,"persistence rmse",round(statistics.mean(x*x for x in e)**.5,3))
for b in bands:
    m=statistics.mean(d[t][b] for t in times)
    e=[d[t][b]-m for t in times]
    print(b,"mean rmse",round(statistics.mean(x*x for x in e)**.5,3))
