import csv, datetime, math, json
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
data=defaultdict(dict)
for r in rows:
    data[r["band"]][r["period_id"]]=(datetime.date.fromisoformat(r["date"]),float(r["y"]))
t0=datetime.date(2020,9,1)
def feats(d):
    doy=d.timetuple().tm_yday
    t=(d-t0).days/365.25
    return (1,t,math.sin(2*math.pi*doy/365.25),math.cos(2*math.pi*doy/365.25),math.sin(4*math.pi*doy/365.25),math.cos(4*math.pi*doy/365.25))
coefs={}
for b in data:
    pts=sorted(data[b].values())
    Xs=[feats(d) for d,v in pts]; Y=[v for d,v in pts]
    n=len(Xs); k=6
    A=[[sum(Xs[i][r]*Xs[i][c] for i in range(n)) for c in range(k)] for r in range(k)]
    Bv=[sum(Xs[i][r]*Y[i] for i in range(n)) for r in range(k)]
    M=[A[i]+[Bv[i]] for i in range(k)]
    for i in range(k):
        p=max(range(i,k),key=lambda r:abs(M[r][i])); M[i],M[p]=M[p],M[i]
        for r in range(k):
            if r!=i:
                f=M[r][i]/M[i][i]
                M[r]=[a-f*b for a,b in zip(M[r],M[i])]
    coefs[b]=[M[i][k]/M[i][i] for i in range(k)]
visits=list(csv.DictReader(open("visits_to_predict.csv")))
pred={}
for v in visits:
    d=datetime.date.fromisoformat(v["date"])
    pred[v["period_id"]]={b: round(sum(coefs[b][j]*feats(d)[j] for j in range(6)),4) for b in sorted(data)}
