import numpy as np, csv, json
from datetime import date
rows=list(csv.DictReader(open("data.csv")))
times=sorted({(r["period_id"],r["date"]) for r in rows}, key=lambda x:x[1])
pids=[t[0] for t in times]; dates=[t[1] for t in times]
bands=["VH","VV","VV-VH"]
vals={b:{} for b in bands}
for r in rows: vals[r["band"]][r["period_id"]]=float(r["y"])
doy=np.array([date.fromisoformat(d).timetuple().tm_yday for d in dates],float)
trend=np.arange(len(doy),dtype=float)
def feats(doy,trend):
    w=2*np.pi*doy/365.0
    return np.column_stack([np.ones_like(doy),np.sin(w),np.cos(w),np.sin(2*w),np.cos(2*w),trend])
X=feats(doy,trend)
coefs={}
for b in bands:
    y=np.array([vals[b][p] for p in pids])
    c,*_=np.linalg.lstsq(X,y,rcond=None)
    coefs[b]=c
fut=list(csv.DictReader(open("visits_to_predict.csv")))
out={}
for i,f in enumerate(fut):
    t=date.fromisoformat(f["date"]).timetuple().tm_yday
    x=feats(np.array([t],float),np.array([len(doy)+i],float))[0]
    out[f["period_id"]]={b:float(x@coefs[b]) for b in bands}
json.dump(out,open("tmp_pred.json","w"),indent=1)
print(json.dumps(out))
