from collections import defaultdict
rows=list(csv.DictReader(open('data.csv')))
d=defaultdict(dict); dates={}
for r in rows: d[r['period_id']][r['band']]=float(r['y']); dates[r['period_id']]=r['date']
ps=sorted(d)
bands=sorted({r['band'] for r in rows})
# monthly climatology per band
clim=defaultdict(lambda: defaultdict(list))
for p in ps:
    for b in bands: clim[b][dates[p][5:7]].append(d[p][b])
clim={b:{m:statistics.mean(v) for m,v in mv.items()} for b,mv in clim.items()}
# recent anomaly: mean of last 6 obs minus their month clim
anom={}
for b in bands:
    rec=[d[p][b] for p in ps[-6:]]
    base=[clim[b][dates[p][5:7]] for p in ps[-6:]]
    anom[b]=statistics.mean(r-c for r,c in zip(rec,base))
