import csv, datetime as dt, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
bands=sorted({r["band"] for r in rows})
hist=defaultdict(dict)
for r in rows:
    hist[dt.date.fromisoformat(r["date"])][r["band"]]=float(r["y"])
hdates=sorted(hist)
hold=hdates[-48:]; train=hdates[:-48]

def doy(d): return (d-dt.date(d.year,1,1)).days
def dd(a,b):
    x=abs(doy(a)-doy(b)); return min(x,366-x)

def evalm(f):
    s=0;n=0
    for d in hold:
        p=f(d)
        for b in bands: s+=(hist[d][b]-p[b])**2; n+=1
    return math.sqrt(s/n)

# seasonal mean window w days
def sm(w):
    def f(d):
        pool=[x for x in train if dd(x,d)<=w]
        return {b: sum(hist[x][b] for x in pool)/len(pool) for b in bands}
    return f
for w in [3,5,7,10,15]:
    print("seasonal w=",w, evalm(sm(w)))

# analog k with weight 1/(dist+1)
def an(k):
    def f(d):
        ds=sorted(train,key=lambda x:dd(x,d))[:k]
        ws=[1/(dd(x,d)+1) for x in ds]
        return {b: sum(w*hist[x][b] for w,x in zip(ws,ds))/sum(ws) for b in bands}
    return f
for k in [1,2,3,5,8]:
    print("analog k=",k, evalm(an(k)))

# seasonal mean + per-band year trend
def smtrend(w=7):
    def f(d):
        pool=[x for x in train if dd(x,d)<=w]
        base={b: sum(hist[x][b] for x in pool)/len(pool) for b in bands}
        # trend: regress band on year using all train
        out={}
        for b in bands:
            ys=sorted(set(x.year for x in train))
            my={y: hist[x][b] for y in ys for x in train if x.year==y}
            ym={y: sum(hist[x][b] for x in train if x.year==y)/sum(1 for x in train if x.year==y) for y in ys}
            # linear fit year->mean
            n=len(ys); mx=sum(ys)/n; myy=sum(ym[y] for y in ys)/n
            slope=sum((y-mx)*(ym[y]-myy) for y in ys)/sum((y-mx)**2 for y in ys)
            out[b]=base[b]+slope*(d.year-ys[-1])
        return out
    return f
print("seasonal+trend", evalm(smtrend()))
