import csv, json, datetime, math
from collections import defaultdict

rows=list(csv.DictReader(open("data.csv")))
data=defaultdict(dict); dates={}
for r in rows:
    data[r["period_id"]][r["band"]]=float(r["y"])
    dates[r["period_id"]]=datetime.date.fromisoformat(r["date"])

periods=sorted(data, key=lambda p: dates[p])
bands=sorted(data[periods[0]])

# climatology: for each band, list of (day_of_year, value)
clim=defaultdict(list)
for p in periods:
    doy=dates[p].timetuple().tm_yday
    for b in bands:
        clim[b].append((doy, data[p][b]))

def doy_dist(a,b):
    d=abs(a-b)%365
    return min(d,365-d)

def predict(band, doy, win=12):
    # weighted average of historical values near this day of year; recency-weighted
    vals=[]
    n=len(clim[band])
    for i,(d,v) in enumerate(clim[band]):
        dd=doy_dist(d,doy)
        if dd<=win:
            w=1.0/(1+dd) * (1 + i/n)   # closer in season & more recent weigh more
            vals.append((w,v))
    if not vals:
        # widen window
        for i,(d,v) in enumerate(clim[band]):
            dd=doy_dist(d,doy)
            w=1.0/(1+dd)*(1+i/n)
            vals.append((w,v))
    sw=sum(w for w,_ in vals)
    return sum(w*v for w,v in vals)/sw

targets=list(csv.DictReader(open("visits_to_predict.csv")))
pred={}
for t in targets:
    pid=t["period_id"]; d=datetime.date.fromisoformat(t["date"])
    doy=d.timetuple().tm_yday
    pred[pid]={b:round(predict(b,doy),6) for b in bands}

json.dump({"prediction":pred,
 "rationale":"Synthetic Historical Control forecast: the parcel's own 171-visit multiband history (2020-09 to 2024-09) was matched seasonally. For each target visit, historical donor observations within +/-12 days of the target day-of-year were matched across all 8 bands, weighted by seasonal proximity and recency, and their band values were transferred as the forecast. This captures the parcel's strong annual phenological cycle (high NDVI/NIR/B8 in the May-Sep growing season, low values in Nov-Mar) while averaging out isolated cloud/noise outliers visible in single visits."},
 open("answer.json","w"), indent=1)
print("wrote", len(pred), "periods")
# sanity: print NDVI predictions for a few dates
for t in targets[::8]:
    print(t["period_id"], t["date"], pred[t["period_id"]]["NDVI"], pred[t["period_id"]]["B8"])
